(function() {

  // ── Google Sheets CSV public URL ──
  var CSV_URL = 'https://docs.google.com/spreadsheets/d/e/2PACX-1vQSfB-FOOv_NO04oJSZMBcoqF_MjB4k6eYa1KgiDLfrqG8DmhKzRlDN_yPV2NjJtkxI7rvV-_3RUjAq/pub?output=csv';

  var YK_ALL = [];       // all parsed companies
  var YK_FILTERED = [];  // after filter/search
  var YK_PAGE = 1;
  var YK_PER_PAGE = 20;
  var YK_ACTIVE_CAT = '전체';
  var YK_ACTIVE_CITY = '';
  var YK_SEARCH = '';

  // ── CSV parser (handles quoted fields) ──
  function parseCSV(text) {
    var rows = [];
    var lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
    for (var i = 1; i < lines.length; i++) {
      var line = lines[i];
      if (!line.trim()) continue;
      var fields = [];
      var cur = '';
      var inQ = false;
      for (var c = 0; c < line.length; c++) {
        var ch = line[c];
        if (ch === '"') {
          if (inQ && line[c+1] === '"') { cur += '"'; c++; }
          else inQ = !inQ;
        } else if (ch === ',' && !inQ) {
          fields.push(cur); cur = '';
        } else {
          cur += ch;
        }
      }
      fields.push(cur);
      if (fields.length >= 5) {
        // Clean address: strip 회비 납부 notes
        var addr = (fields[2] || '').replace(/\s*회비\s*납부.*$/i, '').trim();
        // Parse star rating from column F (e.g. ★★★☆☆ => 3)
        var rawRating = (fields[5] || '').trim();
        var ratingVal = 0;
        for (var ri = 0; ri < rawRating.length; ri++) {
          if (rawRating[ri] === '★') ratingVal++;
        }
        rows.push({
          cat:    fields[0].trim(),
          name:   fields[1].trim(),
          addr:   addr,
          phone:  fields[3].trim(),
          city:   fields[4].trim().toUpperCase().replace(/BẮC /g,'BAC ').replace(/Ắ/g,'A').replace(/Ầ/g,'A'),
          rating: ratingVal
        });
      }
    }
    return rows;
  }

  // ── Build card HTML ──
  function buildStars(n) {
    var html = '<span class="yk-stars">';
    for (var i = 1; i <= 5; i++) {
      html += '<span class="yk-star ' + (i <= n ? 'full' : 'empty') + '">★</span>';
    }
    html += '</span>';
    return html;
  }

  function buildCard(b) {
    var phone = b.phone || '';
    var telHref = phone ? 'tel:' + phone.replace(/[\s\-\(\)~]/g,'').replace(/^\'/, '') : '#';
    var starsHtml = (b.rating > 0) ? buildStars(b.rating) : '';
    return '<div class="yk-card" data-cat="'+escH(b.cat)+'" data-city="'+escH(b.city)+'">' +
      '<div class="yk-card-top">' +
        '<div>' +
          '<div class="yk-card-name">'+escH(b.name)+'</div>' +
          '<div class="yk-card-cat">'+escH(b.cat)+'</div>' +
        '</div>' +
        '<div class="yk-card-meta">' +
          (starsHtml ? starsHtml : '') +
          '<span style="font-size:12px;color:#aaa;">'+escH(b.city)+'</span>' +
        '</div>' +
      '</div>' +
      '<div class="yk-card-info" style="margin-bottom:12px">' +
        (b.addr ? '<div class="yk-card-info-row"><svg class="yk-card-info-icon" viewBox="0 0 24 24"><path d="M21 10c0 7-9 13-9 13S3 17 3 10a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg><span>'+escH(b.addr.substring(0,80))+(b.addr.length>80?'...':'')+'</span></div>' : '') +
        (phone ? '<div class="yk-card-info-row"><svg class="yk-card-info-icon" viewBox="0 0 24 24"><path d="M22 16.92v3a2 2 0 01-2.18 2 19.79 19.79 0 01-8.63-3.07A19.5 19.5 0 014.07 12a19.79 19.79 0 01-3.07-8.67A2 2 0 013 1.18h3a2 2 0 012 1.72c.127.96.361 1.903.7 2.81a2 2 0 01-.45 2.11L7.09 8.91a16 16 0 006 6l1.27-1.27a2 2 0 012.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0122 16.92z"/></svg><span>'+escH(phone)+'</span></div>' : '') +
      '</div>' +
      '<div class="yk-card-actions">' +
        '<a class="yk-btn-primary" href="'+telHref+'"><span class="material-icons-outlined" style="font-size:18px;color:#fff">phone</span> 연락하기</a>' +
        '<a class="yk-btn-secondary" href="#" onclick="ykSearch(\''+escH(b.name).replace(/'/g,"\\'")+'\'  );return false">› 검색</a>' +
      '</div>' +
    '</div>';
  }
//<span class="stitle">CONTACT</span>

  function escH(s) {
    return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  // ── Render grid with current filters ──
  function applyFilters() {
    YK_FILTERED = YK_ALL.filter(function(b) {
      if (YK_ACTIVE_CAT !== '전체' && b.cat !== YK_ACTIVE_CAT) return false;
      if (YK_ACTIVE_CITY && b.city.indexOf(YK_ACTIVE_CITY) === -1) return false;
      if (YK_SEARCH) {
        var q = YK_SEARCH.toLowerCase();
        if (b.name.toLowerCase().indexOf(q) === -1 &&
            b.addr.toLowerCase().indexOf(q) === -1) return false;
      }
      return true;
    });
    YK_PAGE = 1;
    renderYKGrid();
  }

  function renderYKGrid() {
    var grid = document.getElementById('ykGrid');
    var pager = document.getElementById('ykPager');
    var counter = document.getElementById('ykCounter');
    if (!grid) return;

    var total = YK_FILTERED.length;
    var totalPages = Math.ceil(total / YK_PER_PAGE);
    var start = (YK_PAGE - 1) * YK_PER_PAGE;
    var slice = YK_FILTERED.slice(start, start + YK_PER_PAGE);

    if (counter) counter.textContent = total + '개 업체';

    if (slice.length === 0) {
      grid.innerHTML = '<div class="yk-no-result" style="grid-column:1/-1">검색 결과가 없습니다.</div>';
    } else {
      grid.innerHTML = slice.map(buildCard).join('');
    }

    // Pagination
    if (pager) {
      if (totalPages <= 1) { pager.innerHTML = ''; return; }
      var ph = '';
      var sp = Math.max(1, YK_PAGE - 2);
      var ep = Math.min(totalPages, sp + 4);
      sp = Math.max(1, ep - 4);
      ph += YK_PAGE > 1 ? '<button class="bp-arrow" onclick="ykGoPage('+(YK_PAGE-1)+')">&#8249;</button>' : '<button class="bp-arrow disabled">&#8249;</button>';
      if (sp > 1) { ph += '<button class="bp-num" onclick="ykGoPage(1)">1</button>'; if (sp > 2) ph += '<span class="bp-ellipsis">&middot;&middot;&middot;</span>'; }
      for (var p = sp; p <= ep; p++) ph += p === YK_PAGE ? '<button class="bp-num bp-active">'+p+'</button>' : '<button class="bp-num" onclick="ykGoPage('+p+')">'+p+'</button>';
      if (ep < totalPages) { if (ep < totalPages-1) ph += '<span class="bp-ellipsis">&middot;&middot;&middot;</span>'; ph += '<button class="bp-num" onclick="ykGoPage('+totalPages+')">'+totalPages+'</button>'; }
      ph += YK_PAGE < totalPages ? '<button class="bp-arrow" onclick="ykGoPage('+(YK_PAGE+1)+')">&#8250;</button>' : '<button class="bp-arrow disabled">&#8250;</button>';
      pager.innerHTML = ph;
    }
  }

  window.ykGoPage = function(p) { YK_PAGE = p; renderYKGrid(); document.getElementById('lp-yk-directory').scrollIntoView({behavior:'smooth',block:'start'}); };

  window.ykFilter = function(btn) {
    document.querySelectorAll('.yk-filter-btn').forEach(function(b){ b.classList.remove('active'); });
    btn.classList.add('active');
    YK_ACTIVE_CAT = btn.getAttribute('data-cat');
    applyFilters();
  };

  window.ykCityFilter = function(sel) {
    YK_ACTIVE_CITY = sel.value;
    applyFilters();
  };

  window.ykSearch = function(q) {
    if (q !== undefined) {
      var inp = document.getElementById('ykSearchInput');
      if (inp) inp.value = q;
      YK_SEARCH = q;
    } else {
      var inp2 = document.getElementById('ykSearchInput');
      YK_SEARCH = inp2 ? inp2.value.trim() : '';
    }
    applyFilters();
  };

  // ── Build city dropdown from data ──
  function buildCitySelect(data) {
    var cities = {};
    data.forEach(function(b){ if(b.city) cities[b.city] = 1; });
    var cityList = Object.keys(cities).sort();
    var sel = document.getElementById('ykCitySelect');
    if (!sel) return;
    sel.innerHTML = '<option value="">모든 지역</option>';
    cityList.forEach(function(c){
      var opt = document.createElement('option');
      opt.value = c; opt.textContent = c;
      sel.appendChild(opt);
    });
  }

  // ── Build cat filter pills from data ──
  function buildCatFilters(data) {
    var cats = {};
    data.forEach(function(b){ if(b.cat) cats[b.cat] = (cats[b.cat]||0)+1; });
    var wrap = document.getElementById('ykFilters');
    if (!wrap) return;
    var html = '<button class="yk-filter-btn active" data-cat="전체" onclick="ykFilter(this)">전체 ('+data.length+')</button>';
    Object.keys(cats).sort().forEach(function(c){
      html += '<button class="yk-filter-btn" data-cat="'+escH(c)+'" onclick="ykFilter(this)">'+escH(c)+' ('+cats[c]+')</button>';
    });
    wrap.innerHTML = html;
  }

  // ── Detect YELLOWKOREA page ──
  function initYKDirectory() {
    var path = window.location.pathname.toLowerCase();
    var search = window.location.search.toLowerCase();
    var full = path + search;

    // Only activate on the YELLOWKOREA label page or a dedicated page slug
    // e.g. /search/label/YELLOWKOREA  or  /p/yellowkorea.html
    var isYK = full.indexOf('yellowkorea') !== -1 ||
               full.indexOf('yellow-korea') !== -1 ||
               full.indexOf('ko-cham') !== -1;

    if (!isYK) return;

    var dir = document.getElementById('lp-yk-directory');
    if (dir) { dir.classList.add('active'); document.body.classList.add('yk-page'); }

    ['lpSlider','lp-company-section','lp-news-section','blog-pager'].forEach(function(id){
      var el = document.getElementById(id); if(el) el.style.display = 'none';
    });
    document.querySelectorAll('.lp-post-list,.lp-slider').forEach(function(el){ el.style.display='none'; });
    // Hide blog-pager but NOT ykPager
    document.querySelectorAll('.blog-pager:not(#ykPager)').forEach(function(el){ el.style.display='none'; });

    var style = document.createElement('style');
    style.textContent = '#sidebar{display:none!important}.lp-grid{grid-template-columns:1fr!important}#main{max-width:100%!important}';
    document.head.appendChild(style);

    // Show loading
    var grid = document.getElementById('ykGrid');
    if (grid) grid.innerHTML = '<div class="yk-no-result" style="grid-column:1/-1">⏳ 데이터를 불러오는 중...</div>';

    // Fetch CSV
    fetch(CSV_URL)
      .then(function(r){ return r.text(); })
      .then(function(text){
        YK_ALL = parseCSV(text);
        buildCatFilters(YK_ALL);
        buildCitySelect(YK_ALL);
        YK_FILTERED = YK_ALL.slice();
        renderYKGrid();
      })
      .catch(function(err){
        if (grid) grid.innerHTML = '<div class="yk-no-result" style="grid-column:1/-1">⚠️ 데이터 로드 실패. 잠시 후 다시 시도해주세요.</div>';
      });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initYKDirectory);
  } else {
    initYKDirectory();
  }

})();
